ALTER TABLE "identity"."store_invitations" ADD COLUMN "invited_by" uuid;--> statement-breakpoint
UPDATE "identity"."store_invitations" AS "older" SET "revoked_at" = now() WHERE "older"."role" = 'manager' AND "older"."accepted_by" IS NULL AND "older"."revoked_at" IS NULL AND EXISTS (SELECT 1 FROM "identity"."store_invitations" AS "newer" WHERE "newer"."store_id" = "older"."store_id" AND "newer"."email" = "older"."email" AND "newer"."role" = 'manager' AND "newer"."accepted_by" IS NULL AND "newer"."revoked_at" IS NULL AND "newer"."id" > "older"."id");--> statement-breakpoint
CREATE UNIQUE INDEX "store_invitations_one_open_manager_idx" ON "identity"."store_invitations" USING btree ("store_id","email") WHERE "identity"."store_invitations"."role" = 'manager' and "identity"."store_invitations"."accepted_by" is null and "identity"."store_invitations"."revoked_at" is null;
